        ij.i = 0;
        ij.j = 2;
        t_assert(
            H3_EXPORT(localIjToCell)(origin, &ij, 0, &retrieved) == E_FAILED,
            "out of range base cell (2)");
        ij.i = -2;
        ij.j = -2;
        t_assert(
            H3_EXPORT(localIjToCell)(origin, &ij, 0, &retrieved) == E_FAILED,
            "out of range base cell (3)");
