                                  {4, 0}, {-4, 0}, {0, 4}};
        const H3Index expected[] = {0x81283ffffffffff,
                                    0x81293ffffffffff,
                                    0x8150bffffffffff,
                                    0x8151bffffffffff,
                                    H3_NULL,
                                    H3_NULL,
                                    H3_NULL};

        for (int i = 0; i < numCoords; i++) {
            H3Index result;
            const H3Error err =
                H3_EXPORT(localIjToCell)(expected[0], &coords[i], 0, &result);
            if (expected[i] == H3_NULL) {
                t_assert(err != 0, "coordinates out of range");
